const $=(s,c=document)=>c.querySelector(s);const $$=(s,c=document)=>[...c.querySelectorAll(s)];
const months=['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];
const days=['воскресенье','понедельник','вторник','среда','четверг','пятница','суббота'];
const now=new Date();$('#current-date').textContent=`${days[now.getDay()]}, ${now.getDate()} ${months[now.getMonth()]}`;
let currentView='today';const viewHistory=[];
function showView(id,remember=true){if(id===currentView)return;if(remember)viewHistory.push(currentView);currentView=id;$$('.view').forEach(v=>v.classList.toggle('active',v.id===id));$$('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===id));scrollTo({top:0,behavior:'smooth'})}
function goBack(){const previous=viewHistory.pop()||'today';showView(previous,false)}
$$('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));$$('[data-back]').forEach(b=>b.onclick=goBack);
const modal=$('#modal'),content=$('#modal-content');$('.modal-close').onclick=()=>modal.close();
function openMenu(){content.innerHTML=`<div class="app-menu"><div class="eyebrow">МЕНЮ</div><h2>Орбита</h2><button data-menu-view="profile">Профиль</button></div>`;modal.showModal();$$('[data-menu-view]',content).forEach(button=>button.onclick=()=>{modal.close();showView(button.dataset.menuView)})}
$('[data-action="menu"]').onclick=openMenu;
const escapeHTML=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const apiBase=(window.ORBITA_API_URL||'').replace(/\/$/,'');
const planetNames={Sun:'Солнце',Moon:'Луна',Mercury:'Меркурий',Venus:'Венера',Mars:'Марс',Jupiter:'Юпитер',Saturn:'Сатурн',Uranus:'Уран',Neptune:'Нептун',Pluto:'Плутон','True Node':'Северный узел'};
const signNames={Aries:'Овен',Taurus:'Телец',Gemini:'Близнецы',Cancer:'Рак',Leo:'Лев',Virgo:'Дева',Libra:'Весы',Scorpio:'Скорпион',Sagittarius:'Стрелец',Capricorn:'Козерог',Aquarius:'Водолей',Pisces:'Рыбы'};
function zodiac(longitude){const signs=['Овен','Телец','Близнецы','Рак','Лев','Дева','Весы','Скорпион','Стрелец','Козерог','Водолей','Рыбы'];return `${(longitude%30).toFixed(1)}° ${signs[Math.floor((longitude%360)/30)]}`}
function toast(t){const x=$('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2200)}
const readProfile=()=>JSON.parse(localStorage.getItem('orbita-profile')||'null');
const readPartner=()=>JSON.parse(localStorage.getItem('orbita-partner')||'null');
const profileComplete=p=>p&&p.birthdate&&p.birthtime&&p.timezone&&p.latitude&&p.longitude;
function dateInZone(zone){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=t=>parts.find(x=>x.type===t).value;return `${get('year')}-${get('month')}-${get('day')}`}
function profileSignature(p){return [p.birthdate,p.birthtime,p.timezone,p.latitude,p.longitude].join('|')}
function chartRequest(p){return {birth_datetime:`${p.birthdate}T${p.birthtime}:00`,timezone:p.timezone,latitude:Number(p.latitude),longitude:Number(p.longitude),house_system:'P'}}
let currentChart=null,currentPartnerChart=null,currentForecastKey='';
async function loadChart(profile,force=false){const key=`orbita-chart:v3:${dateInZone(profile.timezone)}:${profileSignature(profile)}`;if(!force){const cached=localStorage.getItem(key);if(cached)return JSON.parse(cached)}const response=await fetch(`${apiBase}/v1/natal-chart`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(chartRequest(profile))});const payload=await response.json();if(!response.ok)throw new Error(payload.detail||'Ошибка расчёта');localStorage.setItem(key,JSON.stringify(payload));return payload}
function bindPlaceSearch(form,query,results,state){let timer;query.oninput=()=>{clearTimeout(timer);form.elements.latitude.value='';form.elements.longitude.value='';form.elements.timezone.value='';results.replaceChildren();const value=query.value.trim();if(value.length<2)return;timer=setTimeout(async()=>{state.textContent='Ищем место…';try{const response=await fetch(`${apiBase}/v1/places/search?q=${encodeURIComponent(value)}`);if(!response.ok)throw new Error();const places=await response.json();state.textContent=places.length?'Выберите место из списка':'Ничего не найдено';results.replaceChildren(...places.map(place=>{const button=document.createElement('button');button.type='button';button.textContent=place.label;button.onclick=()=>{query.value=place.label;form.elements.latitude.value=place.latitude;form.elements.longitude.value=place.longitude;form.elements.timezone.value=place.timezone;results.replaceChildren();state.textContent=`Часовой пояс: ${place.timezone}`};return button}))}catch{state.textContent='Не удалось выполнить поиск. Попробуйте ещё раз.'}},350)}}
function requireProfile(title){content.innerHTML=`<div class="result-copy empty-result"><div class="eyebrow">${title}</div><h2>Сначала заполни профиль рождения</h2><p>Без даты рождения персональный результат не формируется. Для натальной карты также нужны точное время и выбранное из списка место.</p><button class="primary-btn" id="go-profile">Перейти в профиль</button></div>`;modal.showModal();$('#go-profile').onclick=()=>{modal.close();showView('profile')}}
async function openNatal(){const profile=readProfile();if(!profileComplete(profile)){requireProfile('МОЯ НАТАЛЬНАЯ КАРТА');return}content.innerHTML=`<div class="loading-card"><span>☉</span><h2>Открываем твою карту</h2><p>Проверяем сохранённый расчёт…</p></div>`;modal.showModal();try{currentChart=await loadChart(profile);renderNatal(currentChart,profile.name||'Моя натальная карта')}catch(error){content.innerHTML=`<div class="result-copy"><h2>Не удалось загрузить карту</h2><p>${escapeHTML(error.message)}</p></div>`}}
function renderNatal(chart,owner='Натальная карта'){const interpretation=chart.interpretation||{};const cards=(interpretation.cards||[]).map((card,index)=>`<details class="reading-card" ${index===0?'open':''}><summary><span><small>${escapeHTML(card.title)}</small><strong>${escapeHTML(card.summary)}</strong></span><b>＋</b></summary><p>${escapeHTML(card.body)}</p></details>`).join('');content.innerHTML=`<div class="result-copy natal-result"><div class="eyebrow">${escapeHTML(owner)} · SWISS EPHEMERIS</div><div class="result-wheel"><span>☉</span></div><h2>${zodiac(chart.angles.ascendant)} — Асцендент</h2><div class="result-tags"><span>ASC · ${zodiac(chart.angles.ascendant)}</span><span>MC · ${zodiac(chart.angles.midheaven)}</span></div><section class="reading-intro"><h3>${escapeHTML(interpretation.headline||'Основные темы карты')}</h3><p>${escapeHTML(interpretation.social_style||'')}</p></section><div class="reading-cards">${cards}</div><p><small>Астрономические данные рассчитаны Swiss Ephemeris. Текст — символическая интерпретация, а не научный вывод.</small></p><button class="primary-btn" onclick="document.querySelector('#modal').close()">Готово</button></div>`}

function openPartnerForm(){const saved=readPartner()||{};content.innerHTML=`<div class="result-copy partner-flow"><div class="eyebrow">НАТАЛЬНАЯ КАРТА ПАРТНЁРА</div><h2>Данные партнёра</h2><p>Имя можно не указывать. Дата, точное время и место нужны для корректного расчёта домов и асцендента.</p><form id="partner-form" class="natal-form"><label>Имя партнёра <small>необязательно</small><input name="name" value="${escapeHTML(saved.name||'')}" placeholder="Например, Юля"></label><label>Дата рождения<input name="birthdate" type="date" value="${escapeHTML(saved.birthdate||'')}" required></label><label>Точное время рождения<input name="birthtime" type="time" value="${escapeHTML(saved.birthtime||'')}" required></label><label>Место рождения<input id="partner-place-query" name="birthplace" value="${escapeHTML(saved.birthplace||'')}" autocomplete="off" placeholder="Начните вводить город" required></label><div class="place-results" id="partner-place-results"></div><input name="latitude" type="hidden" value="${escapeHTML(saved.latitude||'')}"><input name="longitude" type="hidden" value="${escapeHTML(saved.longitude||'')}"><input name="timezone" type="hidden" value="${escapeHTML(saved.timezone||'')}"><div class="form-state" id="partner-place-state">${saved.timezone?`Часовой пояс: ${escapeHTML(saved.timezone)}`:'Выберите город из списка'}</div><button class="primary-btn" type="submit">Рассчитать карту партнёра</button></form></div>`;modal.showModal();const form=$('#partner-form'),query=$('#partner-place-query');bindPlaceSearch(form,query,$('#partner-place-results'),$('#partner-place-state'));form.onsubmit=async event=>{event.preventDefault();const partner=Object.fromEntries(new FormData(form));if(!profileComplete(partner)){toast('Заполни дату, время и выбери место');return}localStorage.setItem('orbita-partner',JSON.stringify(partner));content.innerHTML=`<div class="loading-card"><span>◎</span><h2>Рассчитываем карту</h2><p>Определяем положения планет и домов…</p></div>`;try{currentPartnerChart=await loadChart(partner,true);renderNatal(currentPartnerChart,partner.name?`Карта: ${partner.name}`:'Карта партнёра')}catch(error){content.innerHTML=`<div class="result-copy"><h2>Не удалось рассчитать карту</h2><p>${escapeHTML(error.message)}</p><button class="primary-btn" id="partner-retry">Проверить данные</button></div>`;$('#partner-retry').onclick=openPartnerForm}}}

const arcanaTitles=['Маг','Жрица','Императрица','Император','Иерофант','Влюблённые','Колесница','Справедливость','Отшельник','Колесо Фортуны','Сила','Повешенный','Трансформация','Умеренность','Дьявол','Башня','Звезда','Луна','Солнце','Суд','Мир','Шут'];
const arcanaThemes=['инициатива и способность начинать новое','интуиция и внимательность к скрытым мотивам','созидание, забота и раскрытие ресурсов','структура, ответственность и личные границы','ценности, обучение и передача опыта','выбор, близость и честное партнёрство','движение к цели и управление импульсом','баланс, договорённости и последствия решений','самостоятельный поиск смысла','гибкость в переменах и умение замечать возможности','внутренняя устойчивость и мягкая сила','смена взгляда и принятие необходимой паузы','завершение старого и глубокое обновление','умеренность, ритм и соединение противоположностей','сильные желания, привязанности и материальная энергия','освобождение от неработающих конструкций','надежда, талант и долгосрочное направление','эмоциональная глубина и работа с неопределённостью','ясность, жизненность и открытое самовыражение','переоценка прошлого и зрелый выбор','целостность, завершение и широкий взгляд','свобода, эксперимент и доверие новому опыту'];
function dateDigits(date){return String(date||'').replace(/\D/g,'').split('').map(Number)}
function arcana(...values){const total=values.flatMap(dateDigits).reduce((sum,n)=>sum+n,0);return ((total-1)%22)+1}
function matrixCard(title,number,focus){const name=arcanaTitles[number-1],theme=arcanaThemes[number-1];return `<details class="reading-card"><summary><span><small>${title} · ${number}</small><strong>${name}</strong></span><b>＋</b></summary><p><b>Основная тема:</b> ${theme}. ${focus}</p></details>`}
function openMatrix(){const profile=readProfile();if(!profile?.birthdate){requireProfile('МАТРИЦА СУДЬБЫ');return}const base=arcana(profile.birthdate),day=arcana(profile.birthdate.slice(-2)),month=arcana(profile.birthdate.slice(5,7)),year=arcana(profile.birthdate.slice(0,4)),purpose=arcana(String(base),String(year)),relations=arcana(String(day),String(month)),money=arcana(String(month),String(year));content.innerHTML=`<div class="result-copy matrix-result"><div class="eyebrow">МАТРИЦА СУДЬБЫ · ${escapeHTML(profile.birthdate)}</div><div class="result-wheel"><span>${base}</span></div><h2>${arcanaTitles[base-1]} — центральная энергия</h2><p>Ключевой мотив матрицы — ${arcanaThemes[base-1]}. Ниже — отдельные области, рассчитанные из даты рождения.</p><div class="matrix-summary"><span><b>${purpose}</b>Предназначение</span><span><b>${relations}</b>Отношения</span><span><b>${money}</b>Деньги</span></div><div class="reading-cards">${matrixCard('Характер и способ действовать',base,'В плюсе это помогает опираться на свои сильные стороны; в напряжении может превращаться в повторяющийся сценарий.')}${matrixCard('Внутренний ресурс',day,'Ресурс быстрее восстанавливается, когда ты используешь эту тему осознанно, а не ждёшь подходящего настроения.')}${matrixCard('Социальная реализация',year,'Это направление показывает, как удобнее проявляться в работе, командах и долгих проектах.')}${matrixCard('Предназначение и рост',purpose,'Точка роста — соединить личные способности с пользой для других, сохраняя собственные границы.')}${matrixCard('Любовь и близость',relations,'В отношениях особенно важны прямые договорённости, взаимность и внимание к повторяющимся конфликтам.')}${matrixCard('Деньги и материальные решения',money,'Финансовый потенциал раскрывается через последовательность, проверку рисков и понятные правила.')}</div><p><small>Матрица — нумерологическая символическая система для саморефлексии, а не научный метод или предсказание.</small></p></div>`;modal.showModal()}

const compatibilityAreas=[['Любовь','Эмоциональное притяжение и способность выбирать друг друга.'],['Быт','Совпадение ритмов, привычек и ожиданий от совместной жизни.'],['Секс','Телесная близость, инициатива и свобода говорить о желаниях.'],['Дружба','Интерес друг к другу вне романтики и чувство команды.'],['Партнёрство','Умение договариваться, делить ответственность и выполнять обещания.'],['Веселье','Лёгкость, юмор, спонтанность и совместные впечатления.'],['Конфликты','Способность выдерживать разногласия без разрушения связи.'],['Бизнес','Совместимость ролей, темпа и подхода к решениям.'],['Деньги','Отношение к расходам, накоплениям, риску и общим целям.'],['Дети и семья','Представления о заботе, правилах, доме и будущем.']];
function compatibilityScore(a,b,index){const seed=[...dateDigits(a),...dateDigits(b)].reduce((sum,n,i)=>sum+n*(i+index+1),0);return 4+((seed+index*7)%7)}
function scoreText(score){if(score>=9)return 'Сильное совпадение. Эта сфера может стать опорой пары, если не принимать взаимопонимание как должное.';if(score>=7)return 'Хороший потенциал. Различия здесь скорее дополняют вас, но требуют ясных договорённостей.';if(score>=5)return 'Смешанная динамика. Есть точки притяжения и разные ожидания — их важно проговаривать заранее.';return 'Зона внимания. Разница в потребностях может давать напряжение; помогут конкретные правила и регулярная сверка ожиданий.'}
function openCompatibility(){const profile=readProfile();if(!profile?.birthdate){requireProfile('СОВМЕСТИМОСТЬ');return}const partner=readPartner()||{};content.innerHTML=`<div class="result-copy compatibility-flow"><div class="eyebrow">СОВМЕСТИМОСТЬ</div><h2>${partner.birthdate?'Проверьте данные партнёра':'Добавьте дату рождения партнёра'}</h2><p>Для базовой совместимости достаточно двух дат рождения. Если карта партнёра уже рассчитана, дата подставится автоматически.</p><form id="compatibility-form" class="natal-form"><label>Имя партнёра <small>необязательно</small><input name="name" value="${escapeHTML(partner.name||'')}" placeholder="Имя"></label><label>Дата рождения партнёра<input name="birthdate" type="date" value="${escapeHTML(partner.birthdate||'')}" required></label><button class="primary-btn" type="submit">Рассчитать совместимость</button></form></div>`;modal.showModal();$('#compatibility-form').onsubmit=event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget));const stored=readPartner()||{};localStorage.setItem('orbita-partner',JSON.stringify({...stored,...data}));renderCompatibility(profile,{...stored,...data})}}
function renderCompatibility(profile,partner){const scores=compatibilityAreas.map((area,index)=>({...area,score:compatibilityScore(profile.birthdate,partner.birthdate,index)}));const average=(scores.reduce((sum,item)=>sum+item.score,0)/scores.length).toFixed(1);content.innerHTML=`<div class="result-copy compatibility-result"><div class="eyebrow">${escapeHTML(profile.name||'Ты')} + ${escapeHTML(partner.name||'Партнёр')}</div><div class="compatibility-total"><span>${average}<small>/10</small></span><div><strong>Общий потенциал пары</strong><p>Не итоговая оценка отношений, а ориентир по отдельным сферам.</p></div></div><div class="compatibility-grid">${scores.map(item=>`<details class="compatibility-card"><summary><span><strong>${item[0]}</strong><small>${item[1]}</small></span><b>${item.score}/10</b></summary><p>${scoreText(item.score)}</p></details>`).join('')}</div><section class="compatibility-note"><strong>Как использовать результат</strong><p>Высокие оценки показывают естественные точки опоры. Низкие — темы, где особенно полезны договорённости. Реальная совместимость зависит от поведения, ценностей и безопасности в отношениях.</p></section><p><small>Расчёт по датам рождения является символической интерпретацией и не определяет судьбу пары.</small></p></div>`}
function renderForecastModal(forecast){const overview=forecast.overview||{};content.innerHTML=`<div class="result-copy forecast-modal"><div class="eyebrow">ПРОГНОЗ · ${forecast.date}</div><h2>Подробнее о сегодняшнем дне</h2><div class="forecast-detail"><article><strong>Что может проявиться</strong><p>${overview.what_to_expect||forecast.summary}</p></article><article><strong>Для чего день благоприятен</strong><p>${overview.favorable||''}</p></article><article><strong>Чего лучше избегать</strong><p>${overview.avoid||''}</p></article></div><p class="forecast-note"><small>Прогноз описывает символический фон текущих транзитов, а не гарантированные события.</small></p></div>`;modal.showModal()}
function renderSphere(key){const forecast=currentChart?.daily_forecast,sphere=forecast?.spheres?.[key];if(!sphere)return;const names={relationships:'Отношения',work:'Работа',energy:'Энергия'},icons={relationships:'♡',work:'◇',energy:'ϟ'};content.innerHTML=`<div class="result-copy sphere-popup"><div class="eyebrow">СФЕРА ДНЯ · ${forecast.date}</div><div class="result-wheel"><span>${icons[key]}</span></div><h2>${names[key]}</h2><div class="sphere-score">${sphere.score}/10</div><p>${sphere.summary}</p><div class="do-dont"><div><strong>Благоприятно</strong>${sphere.favorable}</div><div><strong>Осторожнее</strong>${sphere.avoid}</div></div><p><small>Оценка отражает текущие транзиты к натальной карте, а не качество самой сферы жизни.</small></p></div>`;modal.showModal()}
function paintToday(forecast){const scores=forecast.scores,overview=forecast.overview||{},key=forecast.key_transit||{};$('#forecast-date').textContent=forecast.date;$('#forecast-headline').textContent=forecast.headline;$('#forecast-summary').textContent=overview.what_to_expect||forecast.summary;['relationships','work','energy'].forEach(name=>{$(`#score-${name}`).textContent=scores[name];$(`#bar-${name}`).style.setProperty('--score',`${scores[name]*10}%`)});$('#transit-title').textContent=key.title||'Спокойный транзитный фон';$('#forecast-advice').textContent=key.explanation||'';$('#transit-practical').textContent=key.advice||'Сохраняй привычный ритм и заверши начатое.'}
async function refreshToday(force=false){const profile=readProfile();if(!profileComplete(profile))return;const key=dateInZone(profile.timezone);if(!force&&currentForecastKey===key)return;currentForecastKey=key;$('#forecast-headline').textContent='Считаем транзиты дня…';try{currentChart=await loadChart(profile,force);paintToday(currentChart.daily_forecast)}catch{$('#forecast-headline').textContent='Прогноз временно недоступен';$('#forecast-summary').textContent='Проверь подключение и попробуй обновить страницу.'}}
const chartFlows={natal:openNatal,partner:openPartnerForm,matrix:openMatrix,couple:openCompatibility};
$$('[data-flow]').forEach(button=>button.onclick=()=>chartFlows[button.dataset.flow]?.());
$('[data-modal="forecast"]').onclick=async()=>{const profile=readProfile();if(!profileComplete(profile)){showView('profile');return}if(!currentChart)currentChart=await loadChart(profile);renderForecastModal(currentChart.daily_forecast)};
$$('[data-sphere]').forEach(button=>button.onclick=async()=>{const profile=readProfile();if(!profileComplete(profile)){showView('profile');return}if(!currentChart)currentChart=await loadChart(profile);renderSphere(button.dataset.sphere)});
const profileForm=$('#profile-form'),profileQuery=$('#profile-place-query');bindPlaceSearch(profileForm,profileQuery,$('#profile-place-results'),$('#profile-place-state'));
profileForm.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));if(!profileComplete(d)){toast('Выбери место из списка');return}localStorage.setItem('orbita-profile',JSON.stringify(d));currentForecastKey='';currentChart=null;$('#today-title').textContent=d.name||'друг';toast('Профиль сохранён');refreshToday(true)};
const saved=readProfile();if(saved){Object.entries(saved).forEach(([k,v])=>{const el=profileForm.elements[k];if(el)el.value=v});$('#today-title').textContent=saved.name||'друг';if(saved.timezone)$('#profile-place-state').textContent=`Часовой пояс: ${saved.timezone}`}
refreshToday();setInterval(()=>refreshToday(),60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshToday()});
$('#dream-form').onsubmit=e=>{e.preventDefault();const t=$('#dream-text').value.trim();if(!t)return;content.innerHTML=`<div class="result-copy"><div class="eyebrow">ИНТЕРПРЕТАЦИЯ СНА</div><div class="result-wheel"><span>☾</span></div><h2>Сон о переходе</h2><div class="result-tags"><span>Перемены</span><span>Скрытые эмоции</span><span>Поиск опоры</span></div><p>Образ сна может говорить о ситуации, в которой ты чувствуешь неопределённость, но уже готов двигаться дальше. Обрати внимание не только на символы, но и на главное чувство после пробуждения — оно часто точнее любого «сонника».</p><p><small>Это символическая интерпретация, а не предсказание или диагноз.</small></p></div>`;modal.showModal();const item=document.createElement('button');item.className='dream-item';item.innerHTML=`<span>✨</span><div><small>Сегодня</small><strong>${t.slice(0,36)}${t.length>36?'…':''}</strong><p>Новая запись · AI-разбор</p></div><b>→</b>`;$('#dream-list').prepend(item);$('#dream-count').textContent='3 записи';$('#dream-text').value=''};
const replies=['Сегодня лучше опираться на факты и не принимать сильную эмоцию за окончательный вывод. Если решение можно отложить до вечера — дай себе эту паузу.','В твоём контексте повторяющийся образ часто связан не с внешним предсказанием, а с внутренней потребностью в безопасности и ясных границах.','Завтра подходит для встречи, если цель — спокойный разговор. Сложные темы лучше формулировать через свои чувства и конкретные просьбы.'];
function ask(text){if(!text.trim())return;const chat=$('#chat');chat.insertAdjacentHTML('beforeend',`<div class="message user">${text.replace(/[<>]/g,'')}</div>`);setTimeout(()=>{chat.insertAdjacentHTML('beforeend',`<div class="message bot">${replies[Math.floor(Math.random()*replies.length)]}</div>`);scrollTo({top:document.body.scrollHeight,behavior:'smooth'})},450)}
$('#chat-form').onsubmit=e=>{e.preventDefault();ask($('#chat-input').value);$('#chat-input').value=''};$$('.suggestions button').forEach(b=>b.onclick=()=>ask(b.textContent));
$('[data-action="notifications"]').onclick=()=>toast('Утренний прогноз включён');
